function isOzoneComposition(atoms){return atoms.length===3&&atoms.every(a=>a.element==='O')}
function ozoneMarkup(bonds=null){const triangle=bonds&&bonds.length===3;return `<article class="chem-discovery ozone-card"><div class="chem-discovery-text"><p class="eyebrow">${bonds?'TRE OKSYGENATOMER · MODELLFORKLARING':'BLI KJENT MED STOFFET'}</p><h3>Ozon <span>O₃</span></h3>${bonds?`<p class="ozone-notice"><strong>${triangle?'Trekanten er ikke strukturen til vanlig ozon.':'O₃ er formelen til ozon.'}</strong> ${triangle?'Selv om alle bindingsplassene er fylt, viser skissen din en ring. Ozon har en åpen, vinklet struktur.':'Tre oksygenatomer alene betyr ikke at riktig ozonstruktur er bygget.'} Denne enkle byggemodellen med to bindinger per oksygen kan ikke vise ozon korrekt. Her kan du utforske modellen som trengs.</p>`:''}<p>Ozon er en reaktiv gass med tre oksygenatomer i hvert molekyl. Oksygengassen vi puster inn, O₂, har to. Ett ekstra atom gir svært andre egenskaper!</p><h4>Høyt oppe beskytter det oss</h4><p>I stratosfæren absorberer ozon mye av solas skadelige UV-stråling. Ozon dannes og brytes ned i reaksjoner som involverer sollys.</p><h4>Nede ved bakken er det forurensning</h4><p>Her kan ozon dannes når nitrogenoksider og flyktige organiske forbindelser reagerer i sollys. Det kan irritere luftveiene og skade planter.</p><details open><summary>Hvorfor passer ikke de vanlige bindingsplassene?</summary><p>Ozon har 18 valenselektroner. Lewis-modellen bruker én enkeltbinding, én dobbeltbinding og formelle ladninger: + på midtatomet og − på enden med enkeltbinding. Summen er null; ozon er et nøytralt molekyl.</p><p>Vi trenger to resonansformer for å beskrive elektronfordelingen. Molekylet veksler ikke mellom tegningene. I det virkelige molekylet er de to bindingene likeverdige, med bindingsorden mellom enkelt og dobbel.</p></details><p class="note">Kilder: <a href="https://www.epa.gov/ozone-pollution-and-your-patients-health/what-ozone" target="_blank" rel="noreferrer">EPA · ozon i atmosfæren</a> · <a href="https://openstax.org/books/chemistry-2e/pages/7-4-formal-charges-and-resonance" target="_blank" rel="noreferrer">OpenStax · formell ladning og resonans</a></p></div><div class="chem-discovery-visual"><svg viewBox="0 0 420 240" role="img" aria-label="Vinklet ozonmolekyl: midtre oksygen binder til to ender, uten binding mellom endene"><g stroke="#476c60" stroke-width="5"><path d="M80 65 L210 145 L340 65" fill="none"/><path d="M85 85 L210 165 L335 85" fill="none" stroke-dasharray="8 8"/></g>${[[80,65],[210,145],[340,65]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="32" fill="#f5b4a5" stroke="white" stroke-width="4"/><text x="${x}" y="${y+10}" text-anchor="middle" font-size="30" fill="#193c36">O</text>`).join('')}<text x="210" y="220" text-anchor="middle" fill="#476c60" font-size="17">Vinklet form · to likeverdige bindinger</text></svg><div class="ozone-resonance" role="img" aria-label="Resonansformer: O dobbeltbundet til O pluss enkeltbundet til O minus, og motsatt">O=O⁺–O⁻<br><span>↔</span><br>⁻O–O⁺=O</div><p class="note">Forenklede resonansformler. Frie elektronpar er utelatt. Den stiplede linjen i figuren viser den delte, delvise dobbeltbindingskarakteren.</p></div></article>`}
